import * as util from "../api-playground/util";
import {
    DEFAULT_ACTIVE_TAB,
    DEFAULT_BODY_INPUT,
    HTTP_METHODS,
    IMPORT_TOAST_DURATION_MS,
} from "./util";

export function parseAndImportCurl(rawCurlText) {
    const raw = String(rawCurlText ?? "").trim();
    if (!raw) {
        return { error: "Paste a cURL command first." };
    }

    const normalized = raw.replace(/\\\s*\n/g, " ").replace(/\s+/g, " ").trim();

    const methodMatch = normalized.match(/(?:--request|-X)\s+([A-Za-z]+)/i);

    let parsedUrl = "";
    const quotedUrlMatch = normalized.match(/'((?:https?:\/\/)[^']+)'|"((?:https?:\/\/)[^"]+)"/i);
    if (quotedUrlMatch) {
        parsedUrl = quotedUrlMatch[1] || quotedUrlMatch[2] || "";
    } else {
        const plainUrlMatch = normalized.match(/(https?:\/\/\S+)/i);
        parsedUrl = plainUrlMatch?.[1] || "";
    }

    let baseUrl = "";
    let paramsRows = [];

    if (parsedUrl) {
        try {
            const parsed = new URL(parsedUrl);
            baseUrl = `${parsed.origin}${parsed.pathname}`;
            paramsRows = Array.from(parsed.searchParams.entries()).map(([key, value]) => ({
                enabled: true,
                key,
                value,
                description: "",
            }));
        } catch {
            baseUrl = parsedUrl;
        }
    }

    const headerMatches = [...normalized.matchAll(/(?:--header|-H)\s+(?:'([^']*)'|"([^"]*)"|([^\s]+))/gi)];
    const headersRows = headerMatches
        .map((match) => match[1] || match[2] || match[3] || "")
        .map((headerLine) => {
            const separatorIndex = headerLine.indexOf(":");
            if (separatorIndex === -1) return null;
            return {
                enabled: true,
                key: headerLine.slice(0, separatorIndex).trim(),
                value: headerLine.slice(separatorIndex + 1).trim(),
                description: "",
            };
        })
        .filter(Boolean);

    const dataUrlEncodeMatches = [...normalized.matchAll(/--data-urlencode\s+(?:'([^']*)'|"([^"]*)"|([^\s]+))/gi)];
    const dataUrlEncodeParts = dataUrlEncodeMatches
        .map((match) => match[1] || match[2] || match[3] || "")
        .filter(Boolean);

    const bodyMatch = normalized.match(/(?:--data-raw|--data-binary|--data|-d)\s+(?:'([^']*)'|"([^"]*)"|([^\s]+))/i);
    const body = dataUrlEncodeParts.length > 0
        ? dataUrlEncodeParts.join("&")
        : (bodyMatch ? (bodyMatch[1] || bodyMatch[2] || bodyMatch[3] || "") : "");

    const method = (methodMatch?.[1] || (body ? "POST" : "GET")).toUpperCase();

    return {
        baseUrl,
        paramsRows,
        headersRows,
        body,
        method,
    };
}

export function handleImportCurl({
    importCurlText,
    setUrl,
    setParamsRows,
    setHeaderRows,
    setBodyInput,
    setMethod,
    setImportCurlText,
    setImportMessage,
    setShowSuccessToast,
    setActiveTab,
}) {
    const parsed = parseAndImportCurl(importCurlText);

    if (parsed.error) {
        setImportMessage(parsed.error);
        return;
    }

    const emptyRow = util.createEmptyRow();

    if (parsed.baseUrl) {
        setUrl(parsed.baseUrl);
    }

    setParamsRows(parsed.paramsRows.length > 0 ? parsed.paramsRows : [emptyRow]);
    setHeaderRows(parsed.headersRows.length > 0 ? parsed.headersRows : [emptyRow]);
    setBodyInput(util.formatJsonIfPossible(parsed.body || DEFAULT_BODY_INPUT));

    if (HTTP_METHODS.includes(parsed.method)) {
        setMethod(parsed.method);
    }

    setImportCurlText("");
    setImportMessage("");
    setShowSuccessToast(true);
    setTimeout(() => setShowSuccessToast(false), IMPORT_TOAST_DURATION_MS);
    setActiveTab(DEFAULT_ACTIVE_TAB);
} 
